<script setup>
import { computed, onMounted, reactive, ref } from 'vue';
import { api } from '../api.js';
import StatusLabel from './StatusLabel.vue';
const props = defineProps({ path: String });
const id = computed(() => props.path.split('/')[1] || '');
const tab = ref('SUMMARY'), search = ref(''), entries = ref([]), sessions = ref([]), summaries = ref([]), turns = ref([]), jobs = ref([]), taskEvents = ref([]), proposals = ref([]);
const selectedSession = ref(''), error = ref(''), notice = ref(''), busy = ref(false);
const jobPage = ref(1), jobStatus = ref(''), jobTotal = ref(0), jobCounts = ref({});
const form = reactive({ layer: 'L1', content: '', version: null });
const tabs = [{id:'SUMMARY',label:'会话摘要'},{id:'L0',label:'L0 原始证据'},{id:'L1',label:'L1 原子记忆'},{id:'L2',label:'L2 场景'},{id:'L3',label:'L3 用户画像'},{id:'TASKS',label:'处理任务'},{id:'TRASH',label:'回收站'}];
async function load() {
  error.value = '';
  try {
    if (id.value && id.value !== 'new') { const item = await api(`/api/memories/${id.value}`); Object.assign(form, { layer:item.layer, content:item.content, version:item.version }); return; }
    if (!id.value) {
      const [all, history, events, proposalList] = await Promise.all([api('/api/memories'), api('/api/sessions'), api('/api/memory-task-events'), api('/api/memory-proposals')]);
      entries.value=all; sessions.value=history; taskEvents.value=events; proposals.value=proposalList;
      if (!selectedSession.value && history.length) selectedSession.value=history[0].id;
      await Promise.all([loadJobs(), loadSessionData()]);
    }
  } catch(e) { error.value=e.message; }
}
async function loadSessionData(){
  if (!selectedSession.value) { turns.value=[]; summaries.value=[]; return; }
  [turns.value,summaries.value]=await Promise.all([api(`/api/sessions/${selectedSession.value}/turn-blocks`),api(`/api/memory-summaries?sessionId=${encodeURIComponent(selectedSession.value)}`)]);
}
async function loadTurns(){ await loadSessionData(); }
async function loadJobs(){
  const query=new URLSearchParams({page:String(jobPage.value),size:'20'}); if(jobStatus.value)query.set('status',jobStatus.value);
  const result=await api(`/api/memory-jobs?${query}`); jobs.value=result.items; jobTotal.value=result.total; jobCounts.value=result.counts||{};
}
async function selectJobStatus(value){jobStatus.value=value;jobPage.value=1;await loadJobs();}
async function changeJobPage(offset){jobPage.value=Math.max(1,jobPage.value+offset);await loadJobs();}
const jobPages=computed(()=>Math.max(1,Math.ceil(jobTotal.value/20)));
function parseSummary(content){
  try { const value=JSON.parse(content); return {structured:true,currentTopic:value.currentTopic||'',userGoal:value.userGoal||'',verifiedResults:value.verifiedResults||[],completed:value.completed||[],failed:value.failed||[],pending:value.pending||[],decisions:value.decisions||[],raw:content}; }
  catch { return {structured:false,raw:content}; }
}
const filtered=computed(()=>entries.value.filter(item=>tab.value==='TRASH'?item.status==='DELETED':item.layer===tab.value&&item.status!=='DELETED').filter(item=>!search.value||item.content.includes(search.value)));
async function save(){ error.value=''; busy.value=true; try{ await api(id.value==='new'?'/api/memories':`/api/memories/${form.layer}/${id.value}`,{method:id.value==='new'?'POST':'PATCH',body:{layer:form.layer,content:form.content,expectedVersion:form.version}}); location.hash='#/memory'; }catch(e){error.value=e.message;}finally{busy.value=false;} }
async function remove(type,item){ if(!window.confirm(`将 ${type} 记忆移入回收站后会立即停止召回，并使依赖内容进入待重建状态。原始记录仍永久保留，确认继续吗？`))return; busy.value=true; try{await api(`/api/memories/${type}/${item.id||item.runId}?expectedVersion=${item.version}`,{method:'DELETE'});notice.value='已移入回收站';await load();}catch(e){error.value=e.message;}finally{busy.value=false;} }
async function restore(item){busy.value=true;try{await api(`/api/memories/${item.layer}/${item.id}/restore`,{method:'POST'});notice.value='已恢复，索引将在召回时重建';await load();}catch(e){error.value=e.message;}finally{busy.value=false;} }
async function reviseL0(item){const content=window.prompt('输入该轮证据的修订说明。原始工具结果、影响行数和状态机不会被覆盖：',item.userRevision||'');if(!content)return;try{await api(`/api/memories/L0/${item.runId}`,{method:'PATCH',body:{content,expectedVersion:item.version}});await loadTurns();notice.value='修订版本已保存';}catch(e){error.value=e.message;} }
async function restoreL0(item){try{await api(`/api/memories/L0/${item.runId}/restore`,{method:'POST'});await loadTurns();notice.value='原始证据已恢复召回';}catch(e){error.value=e.message;} }
async function editSummary(item){const content=window.prompt('修改会锁定该摘要，后台只会提出更新建议：',item.content);if(!content)return;try{await api(`/api/memories/SUMMARY/${item.id}`,{method:'PATCH',body:{content,expectedVersion:item.version}});notice.value='摘要新版本已保存并锁定';await load();}catch(e){error.value=e.message;} }
async function restoreSummary(item){try{await api(`/api/memories/SUMMARY/${item.id}/restore`,{method:'POST'});notice.value='摘要已恢复';await load();}catch(e){error.value=e.message;} }
async function showRevisions(type,item){try{const list=await api(`/api/memories/${type}/${item.id||item.runId}/revisions`);window.alert(list.length?list.map(v=>`v${v.version} · ${v.operation}\n${v.revisedContent}`).join('\n\n'):'暂无历史版本');}catch(e){error.value=e.message;} }
async function rebuildSummary(){if(!selectedSession.value)return;busy.value=true;try{await api('/api/memories/rebuild',{method:'POST',body:{type:'SUMMARY',sessionId:selectedSession.value}});notice.value='摘要已重建';await load();}catch(e){error.value=e.message;}finally{busy.value=false;} }
async function retry(item){try{await api(`/api/memory-jobs/${item.runId}/retry`,{method:'POST'});notice.value='已重新排队';await loadJobs();}catch(e){error.value=e.message;} }
onMounted(load);
</script>
<template><main class="content-page memory-page" :class="{ 'memory-page-list': !id }">
  <template v-if="!id">
    <div class="page-heading"><div><p class="eyebrow">TRACEABLE MEMORY</p><h1>记忆管理</h1><p class="muted">SQLite 保存权威记录，Redis 加速上下文、召回与异步任务；所有人工修订均保留版本。</p></div><a class="primary link-button" href="#/memory/new">添加长期记忆</a></div>
    <p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="notice" class="notice" role="status">{{ notice }}</p>
    <nav class="tabs memory-tabs" aria-label="记忆层级"><button v-for="item in tabs" :key="item.id" :class="{selected:tab===item.id}" @click="tab=item.id">{{ item.label }}</button></nav>
    <section v-if="tab==='SUMMARY'" class="memory-section"><div class="panel-heading"><div><h2>滚动摘要</h2><p class="muted small">第 25 轮起，每移出窗口 5 个完整轮次增量更新。</p></div><button class="secondary" :disabled="busy||!selectedSession" @click="rebuildSummary">重建当前会话</button></div><label class="search-label">选择会话<select v-model="selectedSession" @change="loadSessionData"><option v-for="item in sessions" :key="item.id" :value="item.id">{{ item.title }}</option></select></label><div v-if="!summaries.length" class="empty-state"><p>尚未达到摘要触发轮次；最近 20 个 TurnBlock 仍会完整加载。</p></div><div v-else class="summary-grid"><article v-for="item in summaries" :key="item.id" class="resource-card summary-card"><div class="resource-heading"><StatusLabel code="SUMMARY" /><span class="badge">v{{ item.version }}</span><span v-if="item.manualLocked" class="badge">人工锁定</span><StatusLabel v-if="item.status==='DELETED'" code="DELETED" compact /></div><template v-if="parseSummary(item.content).structured"><div class="summary-fields"><section><span>当前主题</span><p>{{ parseSummary(item.content).currentTopic || '未记录' }}</p></section><section><span>用户目标</span><p>{{ parseSummary(item.content).userGoal || '未记录' }}</p></section></div><details v-for="field in [{key:'verifiedResults',label:'已验证结果'},{key:'completed',label:'已完成操作'},{key:'failed',label:'失败操作'},{key:'pending',label:'待处理事项'},{key:'decisions',label:'用户决策'}]" :key="field.key" class="summary-list"><summary>{{ field.label }}（{{ parseSummary(item.content)[field.key].length }}）</summary><ul><li v-for="(value,index) in parseSummary(item.content)[field.key]" :key="index">{{ value }}</li><li v-if="!parseSummary(item.content)[field.key].length" class="muted">暂无记录</li></ul></details></template><details v-else class="summary-list"><summary>查看原始摘要</summary><p class="memory-text">{{ item.content }}</p></details><p class="muted small">覆盖第 {{ item.coveredFromTurn }}–{{ item.coveredUntilTurn }} 轮</p><div class="card-actions"><button class="text-button" @click="showRevisions('SUMMARY',item)">版本历史</button><template v-if="item.status==='DELETED'"><button class="text-button" @click="restoreSummary(item)">恢复</button></template><template v-else><button class="text-button" @click="editSummary(item)">修改</button><button class="text-button danger" @click="remove('SUMMARY',item)">移入回收站</button></template></div></article></div></section>
    <section v-else-if="tab==='L0'" class="memory-section"><label class="search-label">选择会话<select v-model="selectedSession" @change="loadTurns"><option v-for="item in sessions" :key="item.id" :value="item.id">{{ item.title }}</option></select></label><div v-if="!turns.length" class="empty-state"><p>当前会话暂无完整轮次。</p></div><div v-else class="turn-list"><details v-for="item in turns" :key="item.runId" class="turn-card"><summary><span><strong>第 {{ item.turn }} 轮</strong><StatusLabel :code="item.mode" compact /><small>{{ item.userMessage }}</small></span><StatusLabel :code="item.deleted?'DELETED':item.status" compact /></summary><div class="turn-body"><h3>用户消息</h3><p>{{ item.userMessage }}</p><h3>执行证据</h3><pre>{{ JSON.stringify(item.events,null,2) }}</pre><h3>最终回复</h3><p>{{ item.assistantFinal||'无最终回复' }}</p><p v-if="item.userRevision" class="notice">用户修订：{{ item.userRevision }}</p><div class="card-actions"><button class="text-button" @click="reviseL0(item)">添加修订</button><button v-if="item.deleted" class="text-button" @click="restoreL0(item)">恢复</button><button v-else class="text-button danger" :disabled="busy" @click="remove('L0',item)">移入回收站</button></div></div></details></div></section>
    <section v-else-if="['L1','L2','L3','TRASH'].includes(tab)" class="memory-section"><label class="search-label">搜索当前视图<input v-model.trim="search" placeholder="输入内容关键词"></label><div v-if="!filtered.length" class="empty-state"><p>暂无匹配记忆。</p></div><div v-else class="resource-grid memory-resource-list"><article v-for="item in filtered" :key="item.id" class="resource-card"><div class="resource-heading"><StatusLabel :code="item.layer" compact /><span class="badge">v{{ item.version }}</span><span class="badge">{{ item.manual?'人工锁定':'自动提取' }}</span><StatusLabel :code="item.status" compact /></div><p class="memory-text">{{ item.content }}</p><p class="small muted">{{ item.sourceSessionId?'来源会话：'+item.sourceSessionId:'手动添加' }}</p><div class="card-actions"><button class="text-button" @click="showRevisions(item.layer,item)">版本历史</button><template v-if="item.status==='DELETED'"><button class="text-button" :disabled="busy" @click="restore(item)">恢复</button></template><template v-else><a :href="`#/memory/${item.id}`">查看 / 修改</a><button class="text-button danger" :disabled="busy" @click="remove(item.layer,item)">移入回收站</button></template></div></article></div></section>
    <section v-else class="memory-section memory-tasks-section"><details class="memory-jobs"><summary><span><strong>自动提取与重建任务</strong><small>共 {{ jobTotal }} 条；待处理 {{ jobCounts.queued||0 }}、处理中 {{ jobCounts.running||0 }}、失败 {{ jobCounts.failed||0 }}</small></span><span class="memory-jobs-toggle">展开</span></summary><div class="memory-jobs-body"><div class="job-filters" role="group" aria-label="记忆任务状态筛选"><button v-for="option in [{v:'',l:'全部'},{v:'QUEUED',l:'待处理'},{v:'RUNNING',l:'处理中'},{v:'FAILED',l:'失败'},{v:'COMPLETED',l:'已完成'}]" :key="option.v" class="text-button" :class="{selected:jobStatus===option.v}" @click="selectJobStatus(option.v)">{{ option.l }}</button></div><div class="memory-job-list"><div v-for="item in jobs" :key="item.runId" class="job-row"><span class="mono small">{{ item.runId.slice(0,8) }}</span><StatusLabel :code="item.status" compact /><span class="muted small">{{ item.error||'' }}</span><button v-if="['FAILED','INTERRUPTED'].includes(item.status)" class="text-button" @click="retry(item)">重试</button></div><p v-if="!jobs.length" class="quiet-state">当前筛选下暂无任务</p></div><div class="job-pagination"><button class="secondary" :disabled="jobPage<=1" @click="changeJobPage(-1)">上一页</button><span>第 {{ jobPage }} / {{ jobPages }} 页</span><button class="secondary" :disabled="jobPage>=jobPages" @click="changeJobPage(1)">下一页</button></div></div></details><details class="memory-jobs"><summary><span><strong>处理事件</strong><small>最近 {{ taskEvents.length }} 条重建与索引事件</small></span><span class="memory-jobs-toggle">展开</span></summary><div class="memory-jobs-body"><div class="memory-job-list"><div v-for="item in taskEvents" :key="`event-${item.id}`" class="job-row"><span class="mono small">{{ item.taskType }}</span><StatusLabel :code="item.status" compact /><span class="muted small">{{ item.message }}</span></div></div></div></details><details class="memory-jobs"><summary><span><strong>人工锁定更新建议</strong><small>共 {{ proposals.length }} 条</small></span><span class="memory-jobs-toggle">展开</span></summary><div class="memory-jobs-body"><div class="memory-job-list"><div v-for="item in proposals" :key="item.id" class="job-row"><span>{{ item.proposedContent }}</span><StatusLabel :code="item.status" compact /></div></div></div></details></section>
  </template>
  <template v-else><a class="back-link" href="#/memory">← 返回记忆管理</a><div class="page-heading"><div><p class="eyebrow">VERSIONED MEMORY</p><h1>{{ id==='new'?'添加长期记忆':'修改长期记忆' }}</h1><p class="muted">保存后内容将人工锁定；后台只能提出更新建议，不能静默覆盖。</p></div></div><form class="form-card" @submit.prevent="save"><label>记忆层级<select v-model="form.layer" :disabled="id!=='new'"><option value="L1">L1 原子记忆</option><option value="L2">L2 场景</option><option value="L3">L3 用户画像</option></select></label><label>记忆内容<textarea v-model="form.content" rows="8" maxlength="2000" required></textarea></label><p v-if="error" class="error" role="alert">{{ error }}</p><div class="form-actions"><button class="primary" :disabled="busy">{{ busy?'保存中…':'保存新版本' }}</button><a class="secondary link-button" href="#/memory">取消</a></div></form></template>
</main></template>
